let _gl, gl;

let dShad, bgShad, moveShad, pShad;

let dPrg, bgPrg, movePrg, pPrg;

let ambient = []; // 色決め用
let accell = 0; // 加速度
let properFrameCount = 0; // カウントも必要

// 板ポリの頂点用。これは位置設定、位置更新、背景のすべてで使う
let position = [
  -1.0,  1.0,  0.0,
  -1.0, -1.0,  0.0,
   1.0,  1.0,  0.0,
   1.0, -1.0,  0.0
];

// 点描画用. といっても具体的な位置ではなくインデックスだけ
// これをもとにして点描画する感じ
let indices = [];

let lineIndices = []; // ここに線描画の情報を格納する

let dVBOList = [];
let bgVBOList = [];
let moveVBOList = [];
let pVBOList = [];

let pIBO;

let fb;
let fb2; // fb2を用意する。
let flip;
// まず最初にfbにvsPとfsPを使って位置と速度を登録。
// 次にfbをmoveに渡して変更してfb2に焼き付ける。
// そしてfb2を使って点描画。
