// 初期設定用シェーダ
// データ送りこみで設定する。256個のデータを用意する感じで。
let vsD=
"precision mediump float;" +
"attribute vec3 aPosition;" + // unique attribute.
"void main(){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

// 色を決めてるところでは位置を決めています。
// ノイズ使って位置と速度を決める！
let fsD=
"precision mediump float;" +
"uniform vec2 uTexSize;" +
"uniform sampler2D uTex;" + // ノイズ計算用乱数テーブル
"uniform float uCount;" + // ノイズ散らすためのカウント
"float TAU = 6.28318;" +
"float PI = 3.14159;" +
// 乱数をuTexから取得
"float getPerlin(float n){" +
"  n = mod(n, 4096.0);" +
"  float picker = mod(n, 4.0);" +
"  n = floor((n - picker)/4.0);" +
"  float x = (mod(n, 32.0) + 0.5) / 32.0;" +
"  float y = (floor(n / 32.0) + 0.5) / 32.0;" +
"  vec4 t = texture2D(uTex, vec2(x, y));" +
"  if(picker == 0.0){ return t.x; }" +
"  if(picker == 1.0){ return t.y; }" +
"  if(picker == 2.0){ return t.z; }" +
"  return t.w;" +
"}" +
// スムーサー。p5.Noiseはこれ使ってるけどここいじればバリエーション
// いろいろできそう。0と1で滑らかにつながる形。
"float scaledCosine(float x){ return 0.5 * (1.0 - cos(PI * x)); }" +
// ノイズ
"float noise(float x, float y, float z){" +
"  x=abs(x);y=abs(y);z=abs(z);" +
"  float xi,yi,zi,xf,yf,zf;" +
"  float rxf; float ryf; float of;" +
"  float result = 0.0;" +
"  float ampl = 0.5;" +
"  float n1; float n2; float n3;" +
"  float ampFallOff = 0.5;" +
"  for(int i=0; i<4; i++){" +
"    xi=floor(x); yi=floor(y); zi=floor(z);" +
"    xf=fract(x); yf=fract(y); zf=fract(z);" +
"    of = xi + yi * 16.0 + zi * 256.0;" +
"    rxf = scaledCosine(xf);" +
"    ryf = scaledCosine(yf);" +

"    n1 = getPerlin(of);" +
"    n1 += rxf * (getPerlin(of + 1.0) - n1);" +
"    n2 = getPerlin(of + 16.0);" +
"    n2 += rxf * (getPerlin(of + 16.0 + 1.0) - n2);" +
"    n1 += ryf * (n2 - n1);" +

"    of += 256.0;" +

"    n2 = getPerlin(of);" +
"    n2 += rxf * (getPerlin(of + 1.0) - n2);" +
"    n3 = getPerlin(of + 16.0);" +
"    n3 += rxf * (getPerlin(of + 16.0 + 1.0) - n3);" +
"    n2 += ryf * (n3 - n2);" +

"    n1 += scaledCosine(zf) * (n2 - n1);" +
"    result += n1 * ampl;" +
"    ampl *= ampFallOff;" +
"    x *= 2.0; y *= 2.0; z *= 2.0;" +
"  }" +
"  return result;" +
"}" +
// メインコード
"void main(){" +
// 2x2の場合は0.5と1.5ですね。
"  vec2 st = gl_FragCoord.xy;" + // 0.0～1.0に正規化
"  float i = floor(st.x);" + // 0.0～255.0のはず。
"  float ny = uCount;" +
"  float nz = uCount / 60.0;" +
"  vec2 position = vec2(noise(i, ny, nz)*2.0-1.0, noise(i+256.0, ny, nz)*2.0-1.0);" +
"  vec2 velocity = vec2(noise(i+512.0, ny, nz)*2.0-1.0, noise(i+768.0, ny, nz)*2.0-1.0)/64.0;" +
"  gl_FragColor = vec4(position, velocity);" + // 初期速度は0で。
"}";

// 背景設定用シェーダ
let vsBG=
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

// 画像を読み込んで表示するだけ
let fsBG=
"precision mediump float;" +
"uniform sampler2D uBG;" +
"uniform vec2 uResolution;" +
"void main(){" +
"  vec2 p = gl_FragCoord.xy / uResolution.xy;" +
"  p.y = 1.0 - p.y;" +
"  gl_FragColor = texture2D(uBG, p);" +
"}";

// 動かす用
// vsはそのままでいい（2x2をfsでフェッチするのにFragCoord使うから）
// というわけでここにboidsを実装します・・！まじか・・・！
let vsMove =
"precision mediump float;" +
"attribute vec3 aPosition;" + // unique attribute.
"void main(){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";
let fsMove =
"precision mediump float;" +
"uniform sampler2D uTex;" +
"uniform vec2 uTexSize;" +
"const float SPEED_LIMIT = 0.04;" +
"void main(){" +
"  vec2 st = gl_FragCoord.xy;" +
// st.y == 0.5のところを横に見ていく感じ
// st.y < 1.0の場合に位置更新。256.0をマジックナンバーで・・うん。
// vec2(0.5+n,st.y)/uTexSizeって感じ(n:0,1,2,...,255)
"  vec2 p = st / uTexSize;" + // この値でそのままアクセス可
"  vec4 t = texture2D(uTex, p);" +
"  vec2 position = t.xy;" +
"  vec2 velocity = t.zw;" +
// 更新処理
"  float centeringFactor = 0.005;" +
"  vec2 center = vec2(0.0);" +
"  float numNeighborsCenter = 0.0;" +
"  float minDistance = 1.0 / 16.0;" +
"  float avoidFactor = 0.05;" +
"  vec2 move = vec2(0.0);" +
"  float matchingFactor = 0.05;" +
"  vec2 avg = vec2(0.0);" +
"  float numNeighborsAverage = 0.0;" +
"  float d;" +
"  vec2 otherPos, otherVel;" +
"  for(float i = 0.0; i < 256.0; i += 1.0){" +
"    if(st.x == i + 0.5){ continue; }" +
"    vec4 other = texture2D(uTex, vec2(0.5 + i, st.y) / uTexSize);" +
"    otherPos = other.xy;" +
"    otherVel = other.zw;" +
"    d = length(position - otherPos);" +
"    if(d < 0.2){" +
"      center += otherPos;" +
"      numNeighborsCenter += 1.0;" +
"      avg += otherVel;" + // otherPos??? 間違えた。てへ！
"      numNeighborsAverage += 1.0;" +
"    }" +
"    if(d < minDistance){" +
"      move += position - otherPos;" +
"    }" +
"  }" +
"  if(numNeighborsCenter > 0.0){" +
"    center /= numNeighborsCenter;" +
"    velocity += (center - position) * centeringFactor;" +
"  }" +
"  velocity += move * avoidFactor;" +
"  if(numNeighborsAverage > 0.0){" +
"    avg /= numNeighborsAverage;" +
"    velocity += avg * matchingFactor;" +
"  }" +
"  float curVel = length(velocity);" +
"  if(curVel > SPEED_LIMIT){" +
"    velocity.x = velocity.x * SPEED_LIMIT / curVel;" +
"    velocity.y = velocity.y * SPEED_LIMIT / curVel;" +
"  }" +
"  float margin = 0.4;" +
"  float turnFactor = 1.0 / 320.0;" +
"  if(position.x < -margin){ velocity.x += turnFactor; }" +
"  if(position.x > margin){ velocity.x -= turnFactor; }" +
"  if(position.y < -margin){ velocity.y += turnFactor; }" +
"  if(position.y > margin){ velocity.y -= turnFactor; }" +
// result.
"  vec4 destColor = vec4(position + velocity, velocity);" +
// ここで・・gl_FragCoord.y > 1.0の場合に、そこから1.0を引いて、
// そうしてできるあれについてtexture2Dしてコピーする。
"  if(st.y > 1.0){" +
"    st.y -= 1.0;" +
"    vec4 prevT = texture2D(uTex, st / uTexSize);" +
"    destColor = prevT;" +
"  }" +
"  gl_FragColor = destColor;" +
"}";

// 点描画用なんだけど、頭をやりたいのよね。
// そこで、点描画の場合にはフラグを使ってポイントスプライト
let vsP =
"precision mediump float;" +
"attribute float aIndex;" + // unique attribute.
"uniform sampler2D uTex;" + // テスト
"uniform vec2 uTexSize;" + // テクスチャフェッチ用(intの方がいいかも)
"uniform float uPointScale;" + // velocityをセットするようです
"varying float vRatio;" + // 後ろほど白く
"varying vec2 vVel;" + // 速度
"varying float vIndex;" + // これが256.0より小さいときにheadを描画
"void main() {" +
// uTexSize * uTexSize個の点を配置
// 0.5を足しているのはきちんとマス目にアクセスするためです
"  float x = (mod(aIndex, uTexSize.x) + 0.5) / uTexSize.x;" +
"  float y = (floor(aIndex / uTexSize.x) + 0.5) / uTexSize.y;" +
"  vIndex = aIndex;" +
"  vRatio = y;" +
"  vec4 t = texture2D(uTex, vec2(x, y));" +
"  vec2 p = t.xy;" +
"  vVel = t.zw;" + // 速度がないと方向が分からないので
"  gl_Position = vec4(p, 0.0, 1.0);" +
"  gl_PointSize = uPointScale;" + // スプライトの場合は16.0？で。
"}";

let fsP =
"precision mediump float;" +
"uniform vec4 uAmbient;" + // パーティクルの色
"uniform bool uIsPoint;" + // pointかどうか
"varying float vRatio;" + // 後ろほど白く
"varying vec2 vVel;" + // 速度
"varying float vIndex;" + // これが256.0より小さいときにheadを描画
"void main(){" +
"  vec4 col = uAmbient * (1.0 - vRatio) + vec4(1.0) * vRatio;" +
// 点描画用のdiscard処理
"  if(uIsPoint){" +
"    if(vIndex > 255.0){ discard; }" +
"    vec2 q = gl_PointCoord.xy;" +
"    if(length(q-0.5)>0.25){ discard; }" +
"  }" +
//"  if(col.a < 0.001){ discard; }" +
"  gl_FragColor = col;" +
"}";

let bg, base, head;

const TEX_SIZE_X = 256; // サンプルが512なので堂々と512で行きます！
const TEX_SIZE_Y = 32;

// ノイズ用
const DATASIZE_X = 32;
const DATASIZE_Y = 32;

let noiseDataShad;  // データ用シェーダ

let vsNoiseData =
"precision mediump float;" +
"attribute float aIndex;" +
"attribute vec4 aData;" +
"uniform vec2 uTexSize;" +
"varying vec4 vData;" +
"void main(){" +
"  vData = aData;" +
"  vec2 p;" +
"  p.x = mod(aIndex, uTexSize.x);" +
"  p.y = floor(aIndex / uTexSize.x);" +
"  p += 0.5;" +
"  p /= uTexSize;" +
"  p = p*2.0-1.0;" +
"  gl_Position = vec4(p, 0.0, 1.0);" + // 各々のpはピクセルの中心
"  gl_PointSize = 1.0;" +
"}";

// おそらくこれでいいはず
let fsNoiseData =
"precision mediump float;" +
"varying vec4 vData;" +
"void main(){" +
"  gl_FragColor = vData;" +
"}";

let noiseDataPrg; // データ用プログラム
let noiseDataLocList = [];
let noiseDataStrideList = [];
let noiseDataVBOList = [];
let noiseDataFB;  // データ用フレームバッファ

function setup() {
  _gl = createCanvas(1112, 834, WEBGL);
  pixelDensity(1);
  gl = _gl.GL; // レンダリングコンテキストの取得

  // 0～TEX_SIZE*TEX_SIZE-1のindexを放り込む
  for(let i = 0; i < TEX_SIZE_X * TEX_SIZE_Y; i++){
    indices.push(i);
  }

  for(let i = 0; i < TEX_SIZE_X; i++){
    for(let k = 0; k < TEX_SIZE_Y - 1; k++){
      lineIndices.push(i + k * TEX_SIZE_X, i + (k + 1) * TEX_SIZE_X);
    }
  }

  // 浮動小数点数テクスチャが利用可能かどうかチェック（可能）
  textureFloatCheck();

  // シェーダー1:点の位置と速度の初期設定用
  dShad = createShader(vsD, fsD);
  dShad.init();
  dPrg = dShad._glProgram;
  // attributeとuniformに関する処理
  dPrg.aPositionLocation = gl.getAttribLocation(dPrg, 'aPosition');
  dPrg.aPositionStride = 3;
  dPrg.uTexLocation = gl.getUniformLocation(dPrg, 'uTex'); // ノイズ用
  // vbo生成
  dVBOList = [create_vbo(position)];

  // シェーダー2:背景用
  bgShad = createShader(vsBG, fsBG);
  bgShad.init();
  bgPrg = bgShad._glProgram;
  // attributeとuniformに関する処理
  bgPrg.aPositionLocation = gl.getAttribLocation(bgPrg, 'aPosition');
  bgPrg.aPositionStride = 3;
  // vbo生成
  bgVBOList = [create_vbo(position)];

  // シェーダー3:点の位置と速度の更新用
  moveShad = createShader(vsMove, fsMove);
  moveShad.init();
  movePrg = moveShad._glProgram;
  // attributeとuniformに関する処理
  movePrg.aPositionLocation = gl.getAttribLocation(movePrg, 'aPosition');
  movePrg.aPositionStride = 3;
  movePrg.uTexLocation = gl.getUniformLocation(movePrg, 'uTex');
  // vbo生成
  moveVBOList = [create_vbo(position)];

  // シェーダー4:点描画用
  // 線描画用に改造
  pShad = createShader(vsP, fsP);
  pShad.init();
  pPrg = pShad._glProgram; // プログラムを使って直接切り替える
  // attributeとuniformに関する処理
  // uniformはテクスチャ以外はsetUniformで放り込めるので不要
  pPrg.aIndexLocation = gl.getAttribLocation(pPrg, 'aIndex');
  pPrg.aIndexStride = 1;
  pPrg.uTexLocation = gl.getUniformLocation(pPrg, 'uTex');
  // vbo生成
  pVBOList = [create_vbo(indices)];
  // ibo生成
  pIBO = create_ibo(lineIndices, Uint16Array);

  fb = create_framebuffer(TEX_SIZE_X, TEX_SIZE_Y, gl.FLOAT);
  fb2 = create_framebuffer(TEX_SIZE_X, TEX_SIZE_Y, gl.FLOAT);
  flip = fb;

  // シェーダー5:ノイズ用
  noiseDataShad = createShader(vsNoiseData, fsNoiseData);
  noiseDataShad.init();
  noiseDataPrg = noiseDataShad._glProgram;
  // attributeとuniformに関する処理
  noiseDataLocList = [gl.getAttribLocation(noiseDataPrg, 'aIndex'), gl.getAttribLocation(noiseDataPrg, 'aData')];
  noiseDataStrideList = [1, 4];
  let IndexArray = [];
  let dataArray = [];
  // 乱数テーブル
  for(let i = 0; i < DATASIZE_X * DATASIZE_Y; i++){
    IndexArray.push(i);
    dataArray.push(Math.random(), Math.random(), Math.random(), Math.random());
  }
  noiseDataVBOList = [create_vbo(IndexArray), create_vbo(dataArray)];
  // ノイズ計算用フレームバッファ
  noiseDataFB = create_framebuffer(DATASIZE_X, DATASIZE_Y, gl.FLOAT);

  // ノイズ用のデフォルト書き込み
  defaultRenderingForNoise();

  // 従来はここでデータ書き込みしてたけど今回はここでノイズを使う
  // 書き込むのは256個だけだけど
  // ってまあいいや、まあいい、えーと。256のとこに従って
  // すべて同じ位置と速度でいい。で、これをクリックの際に呼び出して
  // 初期設定する流れにしましょう。だから→initialize.
  initialize();

  // 背景の用意
  prepareBackground();

  noStroke();

  // head??
  head = createGraphics(32, 32);
  head.noStroke();
  head.fill(255);
  head.triangle(0, 0, 32, 16, 0, 32);
}

function draw(){
  const start = performance.now();

  // ここで位置と速度を更新
  moveRendering();

  // 背景を描画
  resetShader();
  bgShad.useProgram();
  bgShad.setUniform("uBG", bg); // 画像であれば問題ない
  bgShad.bindTextures(); // _drawbuffersを使わないので直接bindする
  // attributeとtexture以外のuniform登録
  set_attribute(bgVBOList, [bgPrg.aPositionLocation], [bgPrg.aPositionStride]);
  bgShad.setUniform("uResolution", [width, height]);
  // ドローコール
  gl.drawArrays(gl.TRIANGLE_STRIP, 0, position.length / 3);

  // 点描画
  pShad.useProgram(); // 基本的にuseProgramで切り替える

  // step.
  properFrameCount++;
  ambient = HSBA_to_RGBA((properFrameCount % 360)/3.6, 100, 80);

  // blendの有効化
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.ONE, gl.ONE);

  // フレームバッファをテクスチャとしてバインド
  gl.bindTexture(gl.TEXTURE_2D, fb2.t);
  gl.uniform1i(pPrg.uTexLocation, 0);
  // attributeとtexture以外のuniform登録
  set_attribute(pVBOList, [pPrg.aIndexLocation], [pPrg.aIndexStride]);
  pShad.setUniform("uTexSize", [TEX_SIZE_X, TEX_SIZE_Y]);
  pShad.setUniform("uPointScale", 16.0);
  pShad.setUniform("uAmbient", ambient);

  // IBOをbindする
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, pIBO);
  // ドローコール
  //gl.drawArrays(gl.POINTS, 0, indices.length);
  pShad.setUniform("uIsPoint", false);
  gl.drawElements(gl.LINES, lineIndices.length, gl.UNSIGNED_SHORT, 0);
  pShad.setUniform("uIsPoint", true);
  gl.drawArrays(gl.POINTS, 0, indices.length);

  gl.flush(); // これにて描画終了

  gl.bindTexture(gl.TEXTURE2D, null); // なんかあった方がいいのかなと
  gl.disable(gl.BLEND); // blendを消しておく

  // swap.
  flip = fb;
  fb = fb2;
  fb2 = flip;

  const end = performance.now();
  const performanceRatio = (end - start) * 60 / 1000;
  bg.image(base, 0, 0);
  bg.text(performanceRatio.toFixed(3), 20, 20);
}

// texture floatが使えるかどうかチェック
function textureFloatCheck(){
  let ext;
  ext = gl.getExtension('OES_texture_float') || gl.getExtension('OES_texture_half_float');
  if(ext == null){
